#!/usr/bin/env bash
# ---------------------------------------------------------------------------
# AUTO-GENERATED by GitHub Copilot
# Purpose: install the underlying delulu-smash framework on this machine: the Python environment
#          (`uv sync`: the `ds` packages, tools and dev dependencies), the pre-commit git hook,
#          git-lfs with the LFS-stored data files (eg pkgs/ds/data/*.parquet), and last
#          `ds settings sync`, which asks for the Pydantic AI Gateway key. Needs `uv`; safe to rerun.
# Usage: a fresh machine gets this through .os/install.sh, which installs uv, runs this, then
#        sets up the OS. Run it directly to (re)install only the framework.
#
# Example CLI Commands:
#   1. Framework only:                  bash .install.sh
#   2. Fresh machine (framework + OS):  .os/install.sh
# ---------------------------------------------------------------------------

# stop at the first failed step instead of running later steps against a half-finished setup
set -euo pipefail

# run from the repo root, wherever this was called from
cd "$(dirname "${BASH_SOURCE[0]}")"

uv sync
# the pre-commit git hook, so `git commit` runs the lint hooks in .pre-commit-config.yaml
# (pre-commit itself is in the pyproject.toml dev group, installed by `uv sync` by default)
uv run pre-commit install
# ffmpeg (docs .mov conversion, gif tools) is not installed here: `os sync` does, from .os/machine.toml

# git-lfs: data files (eg pkgs/ds/data/*.parquet, see .gitattributes) are stored in LFS -- without it
# they're checked out as small pointer files and every read fails ("File out of specification")
if ! git lfs version >/dev/null 2>&1; then
    if command -v pacman >/dev/null 2>&1; then
        sudo pacman -S --needed --noconfirm git-lfs
    elif command -v brew >/dev/null 2>&1; then
        brew install git-lfs
    else
        echo "git-lfs not found: install it with your package manager, then rerun this script" >&2
        exit 1
    fi
fi
git lfs install
git lfs pull

# last, since it is the only step that asks something: stores the Pydantic AI Gateway key (used by all
# ds.ai model calls) in this machine's keyring. Skipping it keeps everything above installed, and keeps
# a key that is already stored. Ctrl+D, not Ctrl+C: polars holds Ctrl+C back until Enter is pressed.
echo "Next: the Pydantic AI Gateway key (from Logfire Gateway > Connect). Ctrl+D skips it for now."
uv run ds settings sync || echo "Gateway key not stored: run \`uv run ds settings sync\` when you have it" >&2
